let raw = $json.output || $json.text || $json.response || $json.message || '';
if (typeof raw !== 'string') raw = JSON.stringify(raw, null, 2);
raw = raw.trim();
const cleanOutput = raw.replace(/\\n/g, '\n').replace(/\\r/g, '').replace(/\\t/g, ' ').replace(/\\"/g, '"').trim();
function extractField(text, fieldName, nextFieldName) {
  const start = text.indexOf(fieldName + ':');
  if (start === -1) return '';
  const valueStart = start + fieldName.length + 1;
  let valueEnd = text.length;
  if (nextFieldName) {
    const nextStart = text.indexOf(nextFieldName + ':', valueStart);
    if (nextStart !== -1) valueEnd = nextStart;
  }
  return text.slice(valueStart, valueEnd).trim();
}
const ticketTitle = extractField(cleanOutput, 'Ticket Title', 'Summary');
const summary = extractField(cleanOutput, 'Summary', 'Category');
const category = extractField(cleanOutput, 'Category', 'Priority');
const priority = extractField(cleanOutput, 'Priority', 'Security Risk');
const securityRisk = extractField(cleanOutput, 'Security Risk', 'Business Impact');
const businessImpact = extractField(cleanOutput, 'Business Impact', 'Recommended Actions');
const recommendedActions = extractField(cleanOutput, 'Recommended Actions', 'Suggested User Response');
const suggestedUserResponse = extractField(cleanOutput, 'Suggested User Response', 'Internal Technical Note');
const internalTechnicalNote = extractField(cleanOutput, 'Internal Technical Note', 'Needs Human Review');
const needsHumanReview = extractField(cleanOutput, 'Needs Human Review', null);
const now = new Date();
const pad = (n) => String(n).padStart(2, '0');
const ticketId = 'TRIAGE-' + now.getUTCFullYear() + pad(now.getUTCMonth() + 1) + pad(now.getUTCDate()) + '-' + pad(now.getUTCHours()) + pad(now.getUTCMinutes()) + pad(now.getUTCSeconds());
function getSlaTarget(value) {
  const p = String(value).toLowerCase();
  if (p.includes('critical')) return '1 hour';
  if (p.includes('high')) return '4 hours';
  if (p.includes('medium')) return '1 business day';
  if (p.includes('low')) return '3 business days';
  return 'To be defined';
}
function getAssignedQueue(value) {
  const c = String(value).toLowerCase();
  if (c.includes('microsoft 365') || c.includes('exchange') || c.includes('teams')) return 'Microsoft 365 Support';
  if (c.includes('entra') || c.includes('azure ad') || c.includes('password') || c.includes('mfa') || c.includes('access')) return 'Identity & Access Support';
  if (c.includes('aws') || c.includes('iam')) return 'Cloud IAM Support';
  if (c.includes('security') || c.includes('phishing')) return 'Security Operations';
  if (c.includes('network') || c.includes('vpn')) return 'Network Support';
  if (c.includes('device') || c.includes('hardware')) return 'Field Support';
  if (c.includes('software') || c.includes('application')) return 'Application Support';
  return 'General IT Support';
}
function shouldEscalate(priorityValue, riskValue, reviewValue) {
  const p = String(priorityValue).toLowerCase();
  const r = String(riskValue).toLowerCase();
  const h = String(reviewValue).toLowerCase();
  return p.includes('critical') || p.includes('high') || r.includes('high') || r.includes('medium') || h.includes('yes') ? 'Yes' : 'No';
}
return [{ json: {
  timestamp: now.toISOString(),
  ticket_id: ticketId,
  ticket_title: ticketTitle,
  summary, category, priority,
  security_risk: securityRisk,
  business_impact: businessImpact,
  recommended_actions: recommendedActions,
  suggested_user_response: suggestedUserResponse,
  internal_technical_note: internalTechnicalNote,
  needs_human_review: needsHumanReview,
  status: 'New',
  sla_target: getSlaTarget(priority),
  assigned_queue: getAssignedQueue(category),
  escalation_required: shouldEscalate(priority, securityRisk, needsHumanReview),
  clean_output: cleanOutput,
  output: cleanOutput
}}];
